// ✅ Bom uso — output depende de input, consumer ganha inferência
export function pick<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): Pick<T, K> {
  const out = {} as Pick<T, K>;
  for (const k of keys) out[k] = obj[k];
  return out;
}
// Uso: const r = pick({ a: 1, b: '2', c: true }, ['a', 'c']);
// r é { a: number; c: boolean } — preservado.

// ✅ Query factory type-safe
export function defineQuery<TData>(config: {
  key: readonly unknown[];
  fetcher: () => Promise<TData>;
}) { return config; }

// Uso: const q = defineQuery({ key: ['user', 1], fetcher: async () => ({ text: 'F' }) });
// q.fetcher retorna Promise<{ text: string }> sem você declarar.

// ❌ Generic inútil
export function log<T>(x: T): any { console.log(x); return x; } // T não agrega

// Result type — força consumer a tratar erro
export type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

export async function fetchUser(id: string): Promise<Result<User, 'not_found' | 'network'>> {
  try {
    const res = await fetch('/api/users/' + id);
    if (res.status === 404) return { ok: false, error: 'not_found' };
    if (!res.ok) return { ok: false, error: 'network' };
    return { ok: true, value: await res.json() };
  } catch {
    return { ok: false, error: 'network' };
  }
}

// Consumer:
const r = await fetchUser('42');
if (r.ok) r.value.name; // TS sabe que existe
else r.error === 'not_found' ? show404() : showError();
